QE = {0: "Now the descent of the scripture is told, come in due course.", 1: "Pointed out by the venerable Siddhas and set forth by the gurus: Bhairava, Bhairavī the Goddess, Svacchanda, Lākula—Aṇurāṭ.", 2: "Gahaneśa—Abjaja, Śakra — the guru, from the crore-fund, studied in sequence from the nine the nine-crore-expanse.", 3: "Then from these the guru distributed a quarter from each crore; both quarters to Dakṣa and the rest, and to Saṃvarta and the rest.", 4: "And a quarter to Vāmana and the rest, half a quarter to Bhārgava; but a quarter-quarter to Bali, and the other quarter-quarter.", 5: "Half to Siṃha; then from the remainder two shares to Garuḍa, a quarter to Vāsuki the serpent — and these are seventeen fragments.", 6: "Half from heaven Rāvaṇa then took; Rāma took half too from this; beginning with Vibhīṣaṇa, obtained through the guru-disciple-rule sequence.", 7: "Divided into nineteen fragments it then became; and each fragment into eight sub-fragments, through the stated quarter-division.", 8: "Quarter, root-extracts in the latter Greater-Uttara, likewise the Kalpa; saṃhitā-kalpa-skandha-…-anuttara, the pervader — threefold, three.", 9: "Here the goddesses are set forth in sequence in expansive form indeed; but in the ninth quarter no count is stated — in the undifferentiated.", 10: "And from Rāma, Lakṣmaṇa; from him the Siddhas; from them too the Dānavas; and the Guhyakas; then from them the Yogins, thence the kings.", 11: "In their sequence, when through time what was amid them lapsed — then, by Śrīkaṇṭhanātha's command, the Siddhas descended.", 12: "Tryambaka, Āmardaka, and renowned Śrīnātha — skilled in nonduality, in duality, and in duality-nonduality, in sequence, in Śiva's teaching.", 13: "And the first's lineage was born; the second through daughter-succession — and that well-established line renowned as Ardhatryambaka.", 14: "And so here four-and-a-half monastic seats in line-succession, spread by disciples and grand-disciples, established hundred-branching.", 15: "Having gathered the essence-juice of the well-seated lineage-stream, this Tantrāloka flows with all rasas.", 16: "The to-be-taken sense of the stated descent is now determined."}


def main() -> int:
    spans = source_spans('tantraloka-a36')
    assert {int(k): v for k, v in TOK.items()} == {k: v for k, v in spans.items()}, 'TOKENS DRIFT'
    assert all(len(TOK[v]) == len(CM[v]) == len(GLOSS[v]) for v in TOK), 'ROW DRIFT'
    json.dump({str(k): v for k, v in TOK.items()}, open('tantraloka-a36/cm/spans-tal-a36.json', 'w'), ensure_ascii=False, indent=1)
    cm = {}
    for v in TOK:
        cm[str(v)] = [[CM[v][i][0], CM[v][i][1], CM[v][i][2]] for i in range(len(TOK[v]))]
    json.dump(cm, open('tantraloka-a36/cm/l0cm-v0-16.json', 'w'), ensure_ascii=False, indent=1)
    t1 = [{"verse_id": "tal-a36-v%02d" % v, "song": "tal-a36", "verse": v, "quick_english": QE[v], "quick_english_source": "manual", "tokens": [{"surface": TOK[v][i], "quick_gloss": GLOSS[v][i]} for i in range(len(TOK[v]))]} for v in sorted(TOK)]
    json.dump(t1, open('tantraloka-a36/working-t1-tal-a36.json', 'w'), ensure_ascii=False, indent=1)
    md = '# Tantraloka-a36 — T1\n*Source: GRETIL tantraloka (KSTS) via workcfg taloka. Span-exact vs source_spans. Machine-proposed, needs human review.*\n'
    for v in sorted(TOK):
        md += '\n\n## tal-a36-v%02d\n' % v
        md += ' '.join('[and]-%s (%s)' % (GLOSS[v][i], TOK[v][i]) for i in range(len(TOK[v]))) + ' // %d //\n' % v
    open('tantraloka-a36/T1-tal-a36.md', 'w').write(md)
    print('cm+t1 written, verses:', len(t1), 'tokens:', sum(len(x) for x in TOK.values()))


if __name__ == '__main__':
    main()
